def memory(captured, garrison=None):
    garrison = garrison or {'アルマムーン': ['アテナ', 'セルリアク', 'レモン', 'ピオーネ']}
    for castle in captured:
        garrison.setdefault(castle, ['ミュスカデ', 'リースリング'])
