    orders = [o for o in interim_candidates(mem).values() if isinstance(o, dict)]
    legs = {(o.get('source'), o.get('target')) for o in orders if o.get('purpose') == 'move'}
    for source, target in legs:
        assert (target, source) not in legs, legs


